<template><PageShell title="物料清单" tcode="CS01"><template #actions><el-button type="primary" @click="visible=true">维护BOM</el-button></template><el-card><div class="toolbar"><el-input v-model="matnr" placeholder="成品物料" /><el-input v-model="werks" placeholder="工厂" /><el-button @click="load">查询</el-button></div><el-table :data="rows" border stripe><el-table-column prop="matnr" label="成品" /><el-table-column prop="werks" label="工厂" /><el-table-column prop="baseQty" label="基准数量" /><el-table-column prop="component" label="组件" /><el-table-column prop="qty" label="组件数量" /></el-table></el-card><el-dialog v-model="visible" title="维护BOM" width="650px"><el-form inline><el-form-item label="成品"><el-input v-model="form.matnr" /></el-form-item><el-form-item label="工厂"><el-input v-model="form.werks" /></el-form-item></el-form><el-table :data="form.items" border><el-table-column label="组件"><template #default="{row}"><el-input v-model="row.component" /></template></el-table-column><el-table-column label="数量"><template #default="{row}"><el-input-number v-model="row.qty" :min="0" /></template></el-table-column></el-table><el-button class="add-line" @click="form.items.push({component:'M1001',qty:1})">添加组件</el-button><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></PageShell></template>
<script setup>
import { onMounted, reactive, ref } from 'vue'; import PageShell from '../../components/PageShell.vue'; import { ppApi } from '../../api'; const rows=ref([]),matnr=ref('F2001'),werks=ref('1000'),visible=ref(false),form=reactive({matnr:'F2001',werks:'1000',baseQty:1,items:[]});async function load(){const x=await ppApi.bom(matnr.value,werks.value);rows.value=x.items||x||[]};async function save(){await ppApi.createBom(form);visible.value=false;load()};onMounted(load)
</script>
